body:
LibGdx 1.6.0 font markupEnabled set to true

<h4>1.Incorrect color if alpha channel missed</h4>

<p>
HTML style color tag without alpha channel produces incorrect color. Color tag <code>[#00FF00]</code> instead of green color gives blue.
</p>


<h4>2.First whitespace before color tag is omitted</h4>

<p>
If font is generated with <code>FreeTypeFontGenerator</code> then first whitespace before color tag disappears.
</p>

Code below reproduces all described issues. 

```
import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.lwjgl.LwjglApplication;
import com.badlogic.gdx.graphics.GL20;
import com.badlogic.gdx.graphics.g2d.BitmapFont;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.graphics.g2d.freetype.FreeTypeFontGenerator;
import com.badlogic.gdx.graphics.g2d.freetype.FreeTypeFontGenerator.FreeTypeFontParameter;

public class BitmapFontMarkupBugExample extends ApplicationAdapter {
    SpriteBatch batch;
    BitmapFont font;
    String alphaChannelBug;
    String whiteSpaceBug;

    public void create () {
        batch = new SpriteBatch();

        FreeTypeFontParameter param = new FreeTypeFontParameter();
        param.size = 26;
        font = new FreeTypeFontGenerator(Gdx.files.internal("data/arial.ttf")).generateFont(param);
        font.getData().markupEnabled = true;

        alphaChannelBug = "1.Alpha channel bug:\n \n"
                + "[GREEN]OK green color [['GREEN'] tag;\n"
                + "[#00FF00FF]OK green color [['#00FF00FF'] tag;\n"
                + "[#00FF00]BUG green color [['#00FF00'] tag";

        whiteSpaceBug = "2.White space bug:\n \n"
                + "OK Sphinx of black quartz\n"
                + "BUG Sphinx [RED]of black quartz";
    }

    public void render () {
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);
        batch.begin();


        font.draw(batch, alphaChannelBug, 100, 400);
        font.draw(batch, whiteSpaceBug, 100, 200);

        batch.end();
    }

    public static void main (String[] args) throws Exception {
        new LwjglApplication(new BitmapFontMarkupBugExample());
    }
}
```
